function UITalentMaterialDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --talentQuestComponent._lastQuestId = 221012
        CfUtils.RefreshTopGoods({QuestConfMgr:GetInstance():GetTalentTicketId()})

        while not self._isCanShow do
            coroutine.yield()
        end
        
        --入口进来
        if checkNumber(KCookie.Get("UITalentMaterialDialogEntry")) == 1 then
            CfUtils.PlayAnimator(self.Item2.transform:Find("RightPanel"), "Play")
            CfUtils.PlayAnimator(self.controller.gameObject.transform:Find("Root/Container/ButtonGroup/AnimRoot"), "Play")
        else
            CfUtils.PlayAnimator(self.Item2.transform:Find("RightPanel"), "Default")
            CfUtils.PlayAnimator(self.controller.gameObject.transform:Find("Root/Container/ButtonGroup/AnimRoot"), "Default")
        end

        coroutine.yield(self:PlayPassAnimator())

        local isHasChallengeCopy = talentQuestComponent:IsHasChallengeCopy()
        if isHasChallengeCopy then 
            self._showCo = cs_coroutine.start(function()
                --coroutine.yield(WaitForSeconds(0.5))
                local buffId = talentQuestComponent:GetBuffIdByQuestId(self._curChallengeQuestId)
                --有buffid
                if checkNumber(buffId) > 0 then
                else
                    local ids = talentQuestComponent:GetCurNeedChooseBuffIds()
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UITalentMaterialLevelSelectionDialog, parameters = {questId = self._curChallengeQuestId, buffIds = ids}}, {
                        {id = Constants.UITypeIds.UITalentMaterialDialog}
                    })
                end
            end)
        end
    end))
    return coWait
end

function UITalentMaterialDialog:FillSelf()
    local isHasChallengeCopy = talentQuestComponent:IsHasChallengeCopy()
    KTool.SetActive(self.Item2, isHasChallengeCopy)
    KTool.SetActive(self.Item1, not isHasChallengeCopy)
    KTool.SetActive(self.BossDrawingNode, isHasChallengeCopy)
    KTool.SetActive(self.DebuffWord, isHasChallengeCopy)
    KTool.SetActive(self.ConsumePop, not isHasChallengeCopy)
    KTool.SetActive(self.ActivityDetails, talentQuestComponent:GetActiveCloseTime() > 0)
    KTool.SetActive(self.FontStyleButtonCancel, isHasChallengeCopy)

    --如果有挑战副本
    if isHasChallengeCopy then
        self._curChooseCopyId = talentQuestComponent:GetCurCopyId()
        self._curChooseCopyVo = QuestConfMgr:GetInstance():GetTalentCopyVo(self._curChooseCopyId)
        self._curChallengeQuestId = QuestConfMgr:GetInstance():GetTalentCurChallengeQuestId()   
        self:FillChallengeCopyInfo()

        local vo = QuestConfMgr:GetInstance():GetTalentCopyVo(self._curChooseCopyId)
        if vo then
            CS.Engine.Lib.KCookie.Set("TalentDifficulty", vo.regionLevel)
        end

        local t = QuestConfMgr:GetInstance():GetTalentQuestIdsByCopyId(self._curChooseCopyId)
        if checkNumber(self._curChallengeQuestId) == checkNumber(t[#t]) and QuestConfMgr:GetInstance():IsPassQuest(self._curChallengeQuestId) then
            KTool.SetActive(self.FontStyleButtonCancel, false)
        end
    else
        self:FillChooseCopy()
    end
end

function UITalentMaterialDialog:PlayPassAnimator()
    local id = talentQuestComponent:GetLastQuestId()
    if id <= 0 then
        return
    end
    
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        return
    end
    CfUtils.SetActive(self.CourseThrough, false)
    CfUtils.SetActive(self.StatusAchieve.transform:Find("UIFX_TalentMaterialStatusAchieve"), false)

    local monstVo = CardConfMgr:GetInstance():GetBaseMonstVo(vo.showMonster)

    if monstVo then
        self.BossDrawingNode2:Execute(checkNumber(monstVo.skinId))
        self.BossDrawingNode3:Execute(checkNumber(monstVo.skinId))
    end

    if self._curChooseCopyVo then
        CfUtils.FillText(self.TextNumberOld, self._curChooseCopyVo.desc) --"P-"..vo.pos)
    end
    CfUtils.FillText(self.TextTitleOld, vo.name)

    KTool.SetActive(self.BossCardOldUp, true)
    KTool.SetActive(self.BossCardOldDown, true)
    CfUtils.PlayAnimator(self.AnimationBossCard, "Play")
    self._co = cs_coroutine.start(function()
        coroutine.yield(WaitForSeconds(2.667))
        KTool.SetActive(self.BossCardOldUp, false)
        KTool.SetActive(self.BossCardOldDown, false)
    end)
    coroutine.yield(WaitForSeconds(2.667))

    if self:IsPassAllQuest() then
        CfUtils.SetActive(self.CourseThrough, true)
        coroutine.yield(WaitForSeconds(0.2))
        CfUtils.SetActive(self.UIFX_TalentMaterialCourseThrough, true)
        CfUtils.SetActive(self.StatusAchieve.transform:Find("UIFX_TalentMaterialStatusAchieve"), true)
    end
end

--buff信息
function UITalentMaterialDialog:FillBuffInfo()
    local t = QuestConfMgr:GetInstance():GetTalentUpBuffDataByPlanId(talentQuestComponent:GetCurPlanId())
    local desc = ""
    local buffDesc = ""
    for k, v in pairs(t) do
        for _, data in pairs(v) do
            desc = QuestConfMgr:GetInstance():GetBuffNameAndImagePath(data)
            local vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(data.upBuff)
            if vo then
                buffDesc = buffDesc..vo.desc
            end
        end
    end
    CfUtils.FillText(self.TxtSeasonState, desc.."<color=#ffc600>"..buffDesc.."</color>")
end

function UITalentMaterialDialog:StartTimeDown()
    self:ClearTimeDown()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local time = talentQuestComponent:GetRemainingTime()
        local timeStr = CfUtils.GetTimeHMS4(time)
        --CfUtils.FillText(self.TxtTime, localize("本赛季剩余时间:_num_", {_num_ = time}))
        CfUtils.FillText(self.TxtTime, timeStr)
        KTool.SetActive(self.ImgTimeLimit, talentQuestComponent:GetActiveCloseTime() > 0)
        KTool.SetActive(self.ActivityDetails, talentQuestComponent:GetActiveCloseTime() > 0)
        if time <= 0 then
            self:ClearTimeDown()
            GameUtils.SecondConfirm(localize("本赛季已结束"), function()
                UIModule.BackDialog()
            end, function()
                UIModule.BackDialog()
            end)
        end
    end, CountDownTime, false, true)
end

function UITalentMaterialDialog:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

--选择副本节点
function UITalentMaterialDialog:FillChooseCopy()
    self._allCopy = QuestConfMgr:GetInstance():GetTalentCopyIdsByPlanId(self._curPlanId)
    local difficulty = checkNumber(CS.Engine.Lib.KCookie.Get("TalentDifficulty"))
    difficulty = (difficulty == 0 and (talentQuestComponent._difficultyMax + 1) or difficulty)

    local copyId = QuestConfMgr:GetInstance():GetTalentCopyIdByPlanIdAndDifficulty(self._curPlanId, difficulty)
    self._curChooseCopyId = (copyId == 0 and self._allCopy[1] or copyId)

    self:RefreshCopyInfo(self._curChooseCopyId)
    self:RefreshArrowBtnStatus()
    self.FontStyleButton:ResetFontStyle("B3", localize("挑战关卡"))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnChooseCopy))
end

--刷新副本信息
function UITalentMaterialDialog:RefreshCopyInfo(copyId)
    copyId = checkNumber(copyId)
    if copyId <= 0 then
        return
    end
    self._curChooseCopyId = copyId

    local vo = QuestConfMgr:GetInstance():GetTalentCopyVo(copyId)
    if not vo then
        return
    end
    CfUtils.FillText(self.TxtChallenge, vo.desc)
    CfUtils.FillText(self.TxtNumber, vo.fight)
    local consumeCount = 1
    CfUtils.FillText(self.Text2, "x"..consumeCount)
    local itemId = QuestConfMgr:GetInstance():GetTalentTicketId()
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(itemId)
    CfUtils.FillImage(self.ConsumeItem, path)

    local rewardId = QuestConfMgr:GetInstance():GetTalentRewardId()
    CfUtils.RefeshGoodGo(self.GoodNode, rewardId, vo.baseReward, 0.9, nil, function()
        GameUtils.ShowCommonGoodsTipsBoard(self.GoodNode, rewardId, true, GoodsUtils.GetThingNo(rewardId))
    end)
end

--刷新按钮状态
function UITalentMaterialDialog:RefreshArrowBtnStatus() 
    local ind = self:GetCopyInd(self._curChooseCopyId)
    KTool.SetActive(self.ImgarrowR, not (ind <= 1))
    KTool.SetActive(self.ImgarrowL, not (ind >= table.count(self._allCopy)))

    local isUnlock, str = talentQuestComponent:IsUnlockCopy(self._allCopy[ind + 1])
    if not isUnlock then
        CfUtils.SetImageColor(self.ImgarrowL, Color(1, 1, 1, 51/255))
    else
        CfUtils.SetImageColor(self.ImgarrowL, Color(1, 1, 1, 1))
    end
end

function UITalentMaterialDialog:OnBtnLeft()
    local ind = self:GetCopyInd(self._curChooseCopyId)
    if ind <= 1 then
        return
    end
    self:RefreshCopyInfo(self._allCopy[ind - 1])
    self:RefreshArrowBtnStatus()
end

function UITalentMaterialDialog:OnBtnRight()
    local ind = self:GetCopyInd(self._curChooseCopyId)
    if ind >= table.count(self._allCopy) then
        return
    end
    local isUnlock, str = talentQuestComponent:IsUnlockCopy(self._allCopy[ind + 1])
    if not isUnlock then
        GameUtils.Toast(str)
        return
    end

    self:RefreshCopyInfo(self._allCopy[ind + 1])
    self:RefreshArrowBtnStatus()

    local go = self.ImgarrowL.transform:Find("redPoint")
    if go then
        KTool.SetActive(go, false)
    end
end

