--进入副本
function UITalentMaterialDialog:OnBtnChooseCopy()
    local vo = QuestConfMgr:GetInstance():GetTalentCopyVo(self._curChooseCopyId)
    if vo then
        CS.Engine.Lib.KCookie.Set("TalentDifficulty", vo.regionLevel)
    end
    talentQuestComponent:EnterCopyReq(self._curChooseCopyId, function()
        self._curChallengeQuestId = QuestConfMgr:GetInstance():GetTalentCurChallengeQuestId()   

        local ids = talentQuestComponent:GetCurNeedChooseBuffIds()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UITalentMaterialLevelSelectionDialog, parameters = {questId = self._curChallengeQuestId, buffIds = ids}}, {
            {id = Constants.UITypeIds.UITalentMaterialDialog}
        })

        --self:FillSelf()
    end)
end

--进入关卡
function UITalentMaterialDialog:OnBtnChooseQuest()
    if self:IsPassAllQuest() then
        GameUtils.Toast(localize("当前课程已通关，请领取奖励"))
        return
    elseif talentQuestComponent:IsTimeClose() then
        GameUtils.Toast(localize("本赛季已结束"))
        return
    end
    local buffId = talentQuestComponent:GetBuffIdByQuestId(self._curChallengeQuestId)
    if checkNumber(buffId) > 0 then
        self:EnterChooseTeam()
    else
        --[[
        local ids = talentQuestComponent:GetCurNeedChooseBuffIds()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UITalentMaterialLevelSelectionDialog, parameters = {questId = self._curChallengeQuestId, buffIds = ids}}, {
            --{id = Constants.UITypeIds.UITalentMaterialDialog}
        })
        ]]
    end
end

--进入选择编队
function UITalentMaterialDialog:EnterChooseTeam()
    local t = QuestConfMgr:GetInstance():GetTalentUpBuffDataByPlanId(self._curPlanId)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = self._curChallengeQuestId, upBuffData = t}}, {
        {id = Constants.UITypeIds.UITalentMaterialDialog}
    })
end

