--领取奖励冰退出
function UITalentMaterialDialog:OnBtnFinalDrawReward()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(QuestConfMgr:GetInstance():GetTalentRewardId())
    vo.goodsId = vo.refId
    local outputNum = talentQuestComponent:GetCurCopyRewardOutPut(true)
