--所有的buff
function UITalentMaterialDialog:FillAllBuff()
    local t = talentQuestComponent:GetCurBuffIds()
    if not t then
        return
    end

    for i = 1, self.Content.transform.childCount do
        local go = self.Content.transform:GetChild(i - 1)
        if go then
            KTool.SetActive(go, false)
        end
    end
    --[[
    local posT = {}
    for i = 1, 5 do
        table.insert(posT, i)
    end
    local _t = {}
    for i = 1, 5 do
        local pos = math.random(5)
        local ind = table.keyof(posT, pos)
        if ind then
            table.insert(_t, pos)
            table.remove(posT, ind)
        else
            table.insert(_t, posT[1])
            table.remove(posT, 1)
        end
    end
    ]]
    local _t = {}
    for k, v in pairs(t) do
        table.insert(_t, {
            id = checkNumber(k),
            buffId = checkNumber(v)
        })
    end
    table.sort(_t, function(a, b)
        return a.id < b.id
    end)
    local count = 1
    for k, data in pairs(_t) do
        local v = data.buffId
        local go = self.Content.transform:Find("DebuffWord"..count)
        if not go then
            go = CfUtils.InstantiateGo(self.Cell, self.Content)
            go.name = "DebuffWord"..count
        end
        KTool.SetActive(go, true)

        if go then
            local vo = QuestConfMgr:GetInstance():GetTalentBuffVo(v)
            if vo then
                local status = checkNumber(vo.quality) - 1
                CfUtils.SetUISwitchImage(go.transform:Find("TitleNode/ImgBar1"), status)
                CfUtils.SetUISwitchImage(go.transform:Find("TitleNode/ImgBar1/ImgBar2"), status)
                if self._curChooseCopyVo then
                    CfUtils.FillText(go.transform:Find("TitleNode/TextNumber"), self._curChooseCopyVo.desc) --"P-"..vo.pos)
                end

                vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(vo.buffId)
                if vo then
                    CfUtils.FillText(go.transform:Find("TextContent"), vo.desc)
                end
            end

            local tarId = KCookie.Get("TalentChooseBuffId")
            if checkNumber(tarId) == checkNumber(data.buffId) then
                CfUtils.PlayAnimation(go, "TalentMaterialDebuffPlay")
                KCookie.Set("TalentChooseBuffId", 0)
            else
                CfUtils.PlayAnimation(go, "TalentMaterialDebuffIdle")
            end
        end
        count = count + 1
    end 
end

--绘制所有的关卡点
function UITalentMaterialDialog:FillQuestPoints()
    local t = QuestConfMgr:GetInstance():GetTalentQuestIdsByCopyId(self._curChooseCopyId)
    if not t then
        return
    end

    for i = 1, #t do
        local go = self.Schedule.transform:Find("PointNode"..i)
        self:FillQuestPoint(go, t[i])

        if i > 1 then
            go = self.Schedule.transform:Find("ImgLine"..i - 1)
            self:FillLine(go, t[i - 1], i == #t)
        end
    end
end

function UITalentMaterialDialog:FillQuestPoint(go, questId)
    if not go or checkNumber(questId) == 0 then
        return
    end
    local status = 1
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(questId)
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockQuest(questId)

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return
    end

    if checkNumber(vo.pointType) == Constants.RoleClass.Boss then
        if isPass then
            status = 5
        elseif isUnlock then
            status = 4
        else
            status = 4 
        end
    else
        if isPass then
            status = 2
        elseif isUnlock then
            status = 3            
        end
    end
    if status == 3 or (status == 4 and isUnlock) then
        KTool.SetActive(go.transform:Find("ImgLight"), true)
        CfUtils.SetUISwitchImage(go.transform:Find("ImgLight"), checkNumber(vo.pointType) == Constants.RoleClass.Boss and 2 or 1)
    else
        KTool.SetActive(go.transform:Find("ImgLight"), false)
    end
    CfUtils.SetUISwitchImage(go.transform:Find("ImgPoint1"), 0)
    CfUtils.SetUISwitchImage(go.transform:Find("ImgPoint1"), status)
end

function UITalentMaterialDialog:FillLine(go, questId, isBoss)
    if not go or checkNumber(questId) == 0 then
        return
    end
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(questId)
    local status = isPass and 2 or 1
    CfUtils.SetUISwitchImage(go, status)
    if isBoss or isPass then
        KTool.SetActive(go.transform:Find("ImgLineBossSelect"), true)
    else
        KTool.SetActive(go.transform:Find("ImgLineBossSelect"), false)
    end
end

--获取副本下标
function UITalentMaterialDialog:GetCopyInd(copyId)
    if checkNumber(copyId) == 0 then
        return 0
    end
    local ind = checkNumber(table.keyof(self._allCopy, checkString(copyId)))
    return ind
end

--是否通关了所有的关卡
function UITalentMaterialDialog:IsPassAllQuest()
    local t = QuestConfMgr:GetInstance():GetTalentQuestIdsByCopyId(self._curChooseCopyId)
    if not t then
        return true
    end
    local ind = checkNumber(table.keyof(t, checkString(talentQuestComponent:GetCurQuestId())))
    if ind >= table.count(t) then
        return true
    end
    return false
end

--活动信息
function UITalentMaterialDialog:OnBtnDetails()
    if self._isShowActivityInfo then
        self._isShowActivityInfo = false
    else
        self._isShowActivityInfo = true
    end 
    KTool.SetActive(self.ActivityInfo, self._isShowActivityInfo)
end 

--buff
function UITalentMaterialDialog:OnBtnBuff()
    if self._isShowBuff then
        self._isShowBuff = false
    else
        self._isShowBuff = true
    end 
    CfUtils.SetUISwitchImage(self.ImgArrow, self._isShowBuff and 2 or 1)
    KTool.SetActive(self.ImgBgDescribe, self._isShowBuff)
end

--展示奖励
function UITalentMaterialDialog:OnBtnShowReard()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UITalentMaterialGetRewardsDialog, parameters = {copyId = self._curChooseCopyId}}, {
        {id = Constants.UITypeIds.UITalentMaterialDialog}
    })
end

function UITalentMaterialDialog:OnRefreshTalentDialog(body)
    self:FillSelf()
end

function UITalentMaterialDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KTool.SetActive(self.controller.gameObject.transform:Find("Root"), false)

        --CfUtils.RefreshTopGoods({QuestConfMgr:GetInstance():GetTalentTicketId()})
        self._isCanShow = false
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
        comp:TalentQuestHomeReq(function()
            self._curPlanId = talentQuestComponent:GetCurPlanId()
            SetButtonAction(self.ImgarrowR, Bind(self, self.OnBtnLeft))
            SetButtonAction(self.ImgarrowL, Bind(self, self.OnBtnRight))
            --SetButtonAction(self.BtnShop, Bind(self, self.OnBtnShop))
            CfUtils.SetActive(self.BtnShop, false)

            --SetButtonAction(self.ImgIcon, Bind(self, self.OnBtnShowReard))
            self.EventRefreshTalentDialog = Events.AddListener(Constants.EventNames.RefreshTalentDialog, Bind(self, self.OnRefreshTalentDialog))
            KTool.SetActive(self.controller.gameObject.transform:Find("Root"), true)

            self:FillBuffInfo()
            self:FillSelf()
            self:StartTimeDown()

            local time = CfUtils.GetTimeHMS4(talentQuestComponent:GetRemainingTime())
            CfUtils.FillText(self.TxtTime, time)
            KTool.SetActive(self.ImgTimeLimit, talentQuestComponent:GetActiveCloseTime() > 0)
            KTool.SetActive(self.ActivityDetails, talentQuestComponent:GetActiveCloseTime() > 0)

            local lastRewards = talentQuestComponent:GetLastTalentRewards()
            if lastRewards and table.count(lastRewards) > 0 then
                GoodsUtils.DrawRewards(lastRewards)
                CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = lastRewards}})
            end

            Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, nil)
            self._isCanShow = true
        end)

        CS.Engine.Lib.KCookie.Set("IsBackUIBattleSelectionMapDialog", 1)
    end))
    return coWait
end

function UITalentMaterialDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            if self._co then
                cs_coroutine.stop(self._co)
                self._co = nil
            end
            if self._showCo then
                cs_coroutine.stop(self._showCo)
                self._showCo = nil
            end
        end
        KCookie.Set("UITalentMaterialDialogEntry", 0)

        Events.RemoveListener(Constants.EventNames.RefreshTalentDialog, self.EventRefreshTalentDialog)
        self:ClearTimeDown()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UITalentMaterialDialog
